import numpy as np


def normal_gradient_score(sigma, field):
    return float(np.max(np.abs(np.gradient(field, sigma, axis=0))))


def fold_preimage_count(x):
    if x < 0:
        return 0
    if x == 0:
        return 1
    return 2


def regular_preimage_count(_x):
    return 1


def main():
    sigma = np.linspace(0.42, 0.66, 801)
    tau = np.linspace(-4.0, 4.0, 401)
    ss, tt = np.meshgrid(sigma, tau, indexing="ij")
    x = ss - 0.5

    # Visual weld-axis ridge: sharp and seam-centered, but generated by a regular chart.
    weld_ridge = np.exp(-(x / 0.012) ** 2) * (1.0 + 0.1 * np.cos(3 * tt))

    # Positivity/localization-axis fold toy: source projection x = u^2 creates a one-sided density.
    positivity_fold = np.zeros_like(x)
    mask = x > 0
    positivity_fold[mask] = 1.0 / np.sqrt(x[mask] + 1e-6) * np.exp(-(tt[mask] / 2.0) ** 2)

    cases = [
        ("weld_visual_ridge_regular_projection", weld_ridge, regular_preimage_count),
        ("positivity_axis_singular_projection", positivity_fold, fold_preimage_count),
    ]

    print("Attempt 01: continuum ridge versus singular projection on the two-axis lens")
    print(
        "Missing lemma candidate:",
        "a visible seam ridge is positivity/localization-bearing only with a singular-projection witness.",
    )
    for name, field, count_fn in cases:
        left = count_fn(-1e-3)
        right = count_fn(1e-3)
        visually_sharp = normal_gradient_score(sigma, field) > 20.0
        has_preimage_jump = left != right
        print("\ncase:", name)
        print(f"  normal_gradient_score={normal_gradient_score(sigma, field):.6g}")
        print(f"  preimage_count_left/right={left}/{right}")
        print(f"  has_preimage_jump={has_preimage_jump}")
        print(f"  visually_sharp={visually_sharp}")
        print(f"  visual_ridge_implies_axis_bearing={visually_sharp and has_preimage_jump}")

    print(
        "\nclaim_tested:",
        "a sharp continuum seam ridge does not by itself locate the positivity/localization axis.",
    )


if __name__ == "__main__":
    main()
